<script setup lang="ts">
import {money,toMinor} from '#shared/utils/pricing'
const db=useDb(),w=useWorkspace(),search=ref(''),category=ref(''),brand=ref(''),active=ref('all'),page=ref(0),editing=ref<Record<string,any>|null>(null),price=ref(''),cost=ref(''),attributes=ref(''),aliases=ref('')
const {error,busy,notice,run}=useAction()
const {data,refresh,pending,error:loadError}=await useAsyncData('catalogue',async()=>check(await db.rpc('catalogue_page',{w:w.value!.id,q:search.value,category_filter:category.value,brand_filter:brand.value,active_filter:active.value,page_number:page.value})) as {rows:Record<string,any>[];count:number},{watch:[search,category,brand,active,page]})
watch([search,category,brand,active],()=>{page.value=0})

async function edit(p?:Record<string,any>){editing.value=p?{...p}:{name:'',sku:'',price_unit:'each',selling_unit:'each',currency:w.value!.currency,active:true,tax_bps:w.value!.tax_bps,attributes:{}};const digits=new Intl.NumberFormat('en',{style:'currency',currency:editing.value.currency}).resolvedOptions().maximumFractionDigits??2;price.value=p?.price_minor!=null?(p.price_minor/10**digits).toString():'';cost.value=p?.cost_minor!=null?(p.cost_minor/10**digits).toString():'';attributes.value=Object.entries(p?.attributes||{}).map(([k,v])=>`${k}: ${v}`).join('\n');aliases.value=p?(check(await db.from('quolyn_product_aliases').select('alias').eq('product_id',p.id))||[]).map(a=>a.alias).join('|'):''}
async function save(){await run(async()=>{const p={...editing.value,workspace_id:w.value!.id,sku:editing.value!.sku||null,price_minor:price.value?toMinor(price.value,editing.value!.currency):null,cost_minor:cost.value?toMinor(cost.value,editing.value!.currency):null,attributes:Object.fromEntries(attributes.value.split('\n').filter(s=>s.includes(':')).map(s=>s.split(/:(.*)/s).slice(0,2).map(x=>x.trim()))),tax_bps:editing.value!.tax_bps===''?null:editing.value!.tax_bps,coverage:editing.value!.coverage||null};const row=check(await db.from('quolyn_products').upsert(p).select().single());check(await db.from('quolyn_product_aliases').delete().eq('workspace_id',w.value!.id).eq('product_id',row.id));const a=aliases.value.split('|').map(s=>s.trim()).filter(Boolean);if(a.length)check(await db.from('quolyn_product_aliases').insert([...new Set(a)].map(alias=>({workspace_id:w.value!.id,product_id:row.id,alias}))));editing.value=null;await refresh();notice.value='Product saved'})}
const unitOptions=await useUnitOptions()
</script>
<template><div><div class="page-title"><div><div class="eyebrow">YOUR SOURCE OF TRUTH</div><h1>Catalogue <span class="badge-count">{{data?.count}} products</span></h1><p>Products, specifications and price bases. Unknowns stay visible.</p></div><div class="row"><NuxtLink class="secondary" to="/import">↑ Import catalogue</NuxtLink><button class="primary" @click="edit()">＋ Add product</button></div></div><p v-if="error||loadError" class="alert error" role="alert">{{error||loadError?.message}}</p><p v-if="notice" class="alert success">{{notice}}</p><div class="toolbar"><input v-model="search" aria-label="Search catalogue" placeholder="Search products, SKU, alias or description…"><input v-model="category" aria-label="Category" placeholder="Category" style="width:150px"><input v-model="brand" aria-label="Brand" placeholder="Brand" style="width:140px"><select v-model="active" aria-label="Product status"><option value="all">All products</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div><div class="table-wrap"><div v-if="pending" class="loading">Loading products…</div><table v-else-if="data?.rows.length"><thead><tr><th>PRODUCT / SKU</th><th>CATEGORY</th><th>PRICE / BASIS</th><th>PACK COVERAGE</th><th>STATUS</th><th></th></tr></thead><tbody><tr v-for="p in data.rows" :key="p.id"><td><button class="link" @click="edit(p)">{{p.name}}</button><small>{{p.sku||'Internal ID · '+p.id.slice(0,8)}} · {{p.brand||'Brand unknown'}}</small></td><td>{{p.category||'—'}}</td><td>{{money(p.price_minor,p.currency)}}<small>per {{p.price_unit}} · tax exclusive</small></td><td>{{p.coverage?`${p.coverage} ${p.coverage_unit}`:'Not configured'}}</td><td><span class="pill" :class="p.active?'confirmed':'rejected'">{{p.active?'Active':'Inactive'}}</span><small>{{p.stock_status}}</small></td><td><button class="link" @click="edit(p)">Edit →</button></td></tr></tbody></table><div v-else class="empty"><div class="empty-icon">▧</div><h3>Your catalogue belongs here</h3><p>Import a spreadsheet or add your first product.</p><NuxtLink to="/import" class="secondary">Import catalogue →</NuxtLink></div></div><div class="row between" style="margin-top:15px"><span class="muted">{{data?.count}} results · 50 per page</span><div class="row"><button class="secondary mini" :disabled="page===0" @click="page--">Previous</button><button class="secondary mini" :disabled="(page+1)*50 >= (data?.count||0)" @click="page++">Next</button></div></div><template v-if="editing"><div class="drawer-backdrop" @click="editing=null"></div><aside class="drawer"><div class="row between"><h2>{{editing.id?'Edit product':'Add product'}}</h2><button class="secondary mini" @click="editing=null">Close</button></div><form @submit.prevent="save"><label>Product name<input v-model="editing.name" required></label><div class="form-grid"><label>SKU<input v-model="editing.sku"></label><label>Manufacturer code<input v-model="editing.manufacturer_code"></label><label>Category<input v-model="editing.category"></label><label>Brand<input v-model="editing.brand"></label></div><label>Description<textarea v-model="editing.description"></textarea></label><div class="form-grid"><label>Selling price (major units)<input v-model="price" placeholder="Leave blank if unknown"></label><label>Currency<input v-model="editing.currency" required maxlength="3"></label><label>Price unit<select v-model="editing.price_unit"><option v-for="u in unitOptions" :key="u">{{u}}</option></select></label><label>Selling unit<input v-model="editing.selling_unit" required></label><label>Pack unit<input v-model="editing.pack_unit" placeholder="box, pack or roll"></label><label>Pack coverage<input v-model="editing.coverage" type="number" step="any" min="0.000001"></label><label>Coverage unit<input v-model="editing.coverage_unit" placeholder="m2 or ft2"></label><label>Cost<input v-model="cost" placeholder="Unknown"></label><label>Cost unit<input v-model="editing.cost_unit"></label><label>Tax (basis points)<input v-model="editing.tax_bps" type="number" min="0" max="10000" placeholder="1800 = 18%; blank = unknown"></label><label>Stock status<input v-model="editing.stock_status"></label></div><label>Lead time<input v-model="editing.lead_time"></label><label>Aliases (separate with |)<input v-model="aliases"></label><label>Specifications (one name: value per line)<textarea v-model="attributes"></textarea></label><label><input v-model="editing.active" type="checkbox">Active product</label><p v-if="error" class="alert error">{{error}}</p><button class="primary" :disabled="busy">Save product</button></form></aside></template></div></template>
